import React, { useState, useEffect } from 'react';
import { FiClock, FiEdit, FiCheck, FiUpload, FiPlay, FiSend, FiDownload, FiX, FiTag } from 'react-icons/fi';
import axios from 'axios';

const EditorVideoCard = ({ video: propVideo, onStatusUpdate }) => {
  // Initialize with prop data or empty defaults
  const [video, setVideo] = useState({
    id: propVideo?.id || '',
    title: propVideo?.title || 'Untitled Project',
    status: propVideo?.status || 'pending',
    thumbnail: propVideo?.thumbnail || 'data:image/jpeg;base64,',
    assignedDate: propVideo?.assignedDate || new Date().toISOString().split('T')[0],
    deadline: propVideo?.deadline || new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    clientNotes: propVideo?.clientNotes || 'No client notes provided',
    rawVideoUrl: propVideo?.rawVideoUrl || '#',
    editedVideoUrl: propVideo?.editedVideoUrl || null,
    editorComments: propVideo?.editorComments || '',
    uuid: propVideo?.uuid || ''
  });

  const [showUploadModal, setShowUploadModal] = useState(false);
  const [uploadedFile, setUploadedFile] = useState(null);
  const [uploadComments, setUploadComments] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Update internal state when prop changes
  useEffect(() => {
    if (propVideo) {
      setVideo({
        id: propVideo.uuid,
        title: propVideo.title,
        status: propVideo.status,
        thumbnail: propVideo.thumbnail || "data:image/jpeg;base64,",
        assignedDate: propVideo.assignedDate,
        deadline: propVideo.deadline,
        clientNotes: propVideo.clientNotes,
        rawVideoUrl: propVideo.rawVideoUrl,
        editedVideoUrl: propVideo.editedVideoUrl,
        editorComments: propVideo.editorComments,
        uuid: propVideo.uuid
      });
    }
  }, [propVideo]);

  // Status configuration
  const statusConfig = {
    pending: {
      icon: <FiClock className="mr-1 text-yellow-500" />,
      text: 'Pending Acceptance',
      bgColor: 'bg-yellow-100',
      textColor: 'text-yellow-800'
    },
    'in-progress': {
      icon: <FiEdit className="mr-1 text-blue-500" />,
      text: 'Editing',
      bgColor: 'bg-blue-100',
      textColor: 'text-blue-800'
    },
    'needs-review': {
      icon: <FiSend className="mr-1 text-purple-500" />,
      text: 'Client Review',
      bgColor: 'bg-purple-100',
      textColor: 'text-purple-800'
    },
    completed: {
      icon: <FiCheck className="mr-1 text-green-500" />,
      text: 'Completed',
      bgColor: 'bg-green-100',
      textColor: 'text-green-800'
    },
    verified : {
      icon: <FiCheck className="mr-1 text-green-500" />,
      text: 'verfication completed',
      bgColor: 'bg-green-100',
      textColor: 'text-green-800'
    }
  };

  const { icon, text, bgColor, textColor } = statusConfig[video.status] || statusConfig.pending;

  // Action handlers
  const handleAccept = async () => {
    try {
      setLoading(true);
      console.log("Sending update for video:", {
        status: 'in-progress',
        videoId: video.uuid // Make sure this exists
      });

      await axios.patch(`http://localhost:3000/api/videos/status`, { 
        status: 'in-progress',
        videoId: video.uuid 
      }, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      
      setVideo({...video, status: 'in-progress'});
      if (onStatusUpdate) onStatusUpdate(video.uuid, 'in-progress');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to accept project');
    } finally {
      setLoading(false);
    }
  };

  const handleReject = async () => {
    if (confirm('Are you sure you want to reject this assignment?')) {
      try {
        setLoading(true);
        console.log("Sending update for video:", {
          status: 'in-progress',
          videoId: video.uuid // Make sure this exists
        });
        await axios.patch(`http://localhost:3000/api/videos/status`, { 
          status: 'rejected',
          videoId: video.uuid 
        }, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        
        if (onStatusUpdate) onStatusUpdate(video.uuid, 'rejected');
        alert('Assignment rejected. Admin will be notified.');
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to reject project');
      } finally {
        setLoading(false);
      }
    }
  };

  const handleFileChange = (e) => {
    setUploadedFile(e.target.files[0]);
  };


  const [videoTitle, setVideoTitle] = useState(propVideo?.title || '');
  const [videoDescription, setVideoDescription] = useState(propVideo?.description ||'');
  const [videoTags, setVideoTags] = useState(propVideo?.tags?.join(', ') || '');


  const handleSubmitForReview = async () => {
    if (!uploadedFile) {
      alert('Please upload a file first');
      return;
    }
    
    try {
      setLoading(true);
      
      // Upload the file
      const formData = new FormData();
      formData.append('video', uploadedFile);
      formData.append('comments', uploadComments);
      formData.append('title', videoTitle);
      formData.append('description', videoDescription);
      formData.append('tags', videoTags);
      formData.append('id', video.uuid); 
      
      const response = await axios.post(`http://localhost:3000/api/upload_edited`, formData, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'multipart/form-data'
        }
      });
      
      // Update local state
      setVideo({
        ...video,
        title: videoTitle,
        description: videoDescription,
        tags: videoTags.split(',').map(tag => tag.trim()),
        editedVideoUrl: response.data.fileUrl,
        status: 'needs-review',
        editorComments: uploadComments || video.editorComments
      });
      
      if (onStatusUpdate) onStatusUpdate(video.uuid, 'needs-review');
      
      setShowUploadModal(false);
      setUploadedFile(null);
      setUploadComments('');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to submit video');
    } finally {
      setLoading(false);
    }
  };

  const handleMarkComplete = async () => {
    try {
      setLoading(true);
      await axios.patch(`/api/videos/${video.uuid}/status`, { 
        status: 'completed' 
      }, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      
      setVideo({...video, status: 'completed'});
      if (onStatusUpdate) onStatusUpdate(video.uuid, 'completed');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to complete project');
    } finally {
      setLoading(false);
    }
  };

  const handleAddComments = async () => {
    const comments = prompt("Add your editor's notes:", video.editorComments);
    if (comments !== null) {
      try {
        setLoading(true);

        await axios.patch(`/api/videos/${video.uuid}/comments`, { 
          comments 
        }, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        
        setVideo({...video, editorComments: comments});
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to update comments');
      } finally {
        setLoading(false);
      }
    }
  };


  


  const handleDownload = (url, filename) => {
    // In a real app, you would trigger a proper download
    window.open(url, '_blank');
  };

  return (
    <>
       {/* Upload Modal */}
       {showUploadModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full max-h-[90vh] overflow-y-auto">
            <div className="flex justify-between items-center mb-4">
              <h3 className="font-semibold text-lg">Upload Edited Video</h3>
              <button 
                onClick={() => setShowUploadModal(false)} 
                className="text-gray-500 hover:text-gray-700"
                disabled={loading}
              >
                <FiX size={20} />
              </button>
            </div>
            
            {error && (
              <div className="mb-4 p-2 bg-red-100 text-red-700 rounded text-sm">
                {error}
              </div>
            )}
            
            {/* Video Title */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">Video Title</label>
              <input
                type="text"
                value={videoTitle}
                onChange={(e) => setVideoTitle(e.target.value)}
                className="w-full border border-gray-300 rounded-md p-2 text-sm"
                placeholder="Enter video title"
              />
            </div>

            {/* Video Description */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
              <textarea
                value={videoDescription}
                onChange={(e) => setVideoDescription(e.target.value)}
                className="w-full border border-gray-300 rounded-md p-2 text-sm"
                rows="3"
                placeholder="Enter video description"
              />
            </div>

            {/* Video Tags */}
            <div className="mb-4">
              <label className=" text-sm font-medium text-gray-700 mb-1 flex items-center">
                <FiTag className="mr-1" /> Tags (comma separated)
              </label>
              <input
                type="text"
                value={videoTags}
                onChange={(e) => setVideoTags(e.target.value)}
                className="w-full border border-gray-300 rounded-md p-2 text-sm"
                placeholder="e.g., travel, vlog, summer"
              />
              <p className="text-xs text-gray-500 mt-1">Separate tags with commas</p>
            </div>
            
            {/* File Upload */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">Select Video File</label>
              <input 
                type="file" 
                accept="video/*" 
                onChange={handleFileChange}
                disabled={loading}
                className="block w-full text-sm text-gray-500
                  file:mr-4 file:py-2 file:px-4
                  file:rounded-md file:border-0
                  file:text-sm file:font-semibold
                  file:bg-blue-50 file:text-blue-700
                  hover:file:bg-blue-100"
              />
              {uploadedFile && (
                <p className="mt-2 text-sm text-gray-600">
                  Selected: {uploadedFile.name} ({(uploadedFile.size / (1024 * 1024)).toFixed(2)} MB)
                </p>
              )}
            </div>
            
            {/* Editor Comments */}
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-1">Editor Notes</label>
              <textarea
                value={uploadComments}
                onChange={(e) => setUploadComments(e.target.value)}
                disabled={loading}
                className="w-full border border-gray-300 rounded-md p-2 text-sm"
                rows="3"
                placeholder="Add any notes about your edits..."
              />
            </div>
            
            <div className="flex justify-end space-x-2">
              <button
                onClick={() => setShowUploadModal(false)}
                disabled={loading}
                className="px-4 py-2 text-sm bg-gray-100 hover:bg-gray-200 rounded-md"
              >
                Cancel
              </button>
              <button
                onClick={handleSubmitForReview}
                disabled={loading || !uploadedFile}
                className="px-4 py-2 text-sm bg-purple-600 hover:bg-purple-700 text-white rounded-md flex items-center"
              >
                {loading ? 'Submitting...' : (
                  <>
                    <FiSend className="mr-2" /> Submit for Review
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}


      {/* Error message */}
      {error && !showUploadModal && (
        <div className="mb-2 p-2 bg-red-100 text-red-700 rounded text-sm">
          {error}
        </div>
      )}

      {/* Video Card */}
      <div className="max-w-sm bg-white rounded-lg shadow-md overflow-hidden border border-gray-200 hover:shadow-lg transition-shadow">
        {/* Thumbnail with status */}
        <div className="relative">
          <img 
            src={video.thumbnail} 
            alt={video.title} 
            className="w-full h-48 object-cover"
          />
          <div className={`absolute top-2 left-2 ${bgColor} ${textColor} px-2 py-1 rounded text-xs flex items-center`}>
            {icon}
            {text}
          </div>
          {new Date(video.deadline) < new Date() && video.status !== 'completed' && (
            <div className="absolute top-2 right-2 bg-red-100 text-red-800 px-2 py-1 rounded text-xs">
              Overdue
            </div>
          )}
        </div>

        {/* Video info */}
        <div className="p-4">
          <h3 className="font-semibold text-lg mb-1">{video.title}</h3>
          
          <div className="flex justify-between text-sm mb-2">
            <span className="text-gray-600">Assigned: {video.assignedDate}</span>
            <span className={`font-medium ${
              new Date(video.deadline) < new Date() && video.status !== 'completed' 
                ? 'text-red-600' 
                : 'text-gray-700'
            }`}>
              Deadline: {video.deadline}
            </span>
          </div>

          {/* Client notes */}
          <div className="mb-3 bg-gray-50 p-2 rounded">
            <p className="text-sm text-gray-600">
              <span className="font-medium">Client Notes: </span>
              {video.clientNotes}
            </p>
          </div>

          {/* Editor comments (if any) */}
          {video.editorComments && (
            <div className="mb-3 bg-blue-50 p-2 rounded">
              <p className="text-sm text-blue-700">
                <span className="font-medium">Your Comments: </span>
                {video.editorComments}
              </p>
            </div>
          )}

          {/* Action buttons */}
          <div className="flex flex-wrap gap-2">
            {/* Preview/download buttons */}
            <button 
              onClick={() => handleDownload(video.rawVideoUrl, `${video.title}-raw.mp4`)}
              className="text-sm bg-gray-100 hover:bg-gray-200 px-3 py-1 rounded flex items-center"
              disabled={loading}
            >
              <FiPlay className="mr-1" /> Preview
            </button>
            
            {video.editedVideoUrl && (
              <button 
                onClick={() => handleDownload(video.editedVideoUrl, `${video.title}-edited.mp4`)}
                className="text-sm bg-green-100 hover:bg-green-200 text-green-800 px-3 py-1 rounded flex items-center"
                disabled={loading}
              >
                <FiDownload className="mr-1" /> Download Edits
              </button>
            )}

            {/* Status-specific buttons */}
            {video.status === 'pending' && (
              <>
                <button 
                  onClick={handleAccept}
                  disabled={loading}
                  className="text-sm bg-green-100 hover:bg-green-200 text-green-800 px-3 py-1 rounded flex items-center"
                >
                  {loading ? 'Accepting...' : (
                    <>
                      <FiCheck className="mr-1" /> Accept
                    </>
                  )}
                </button>
                <button 
                  onClick={handleReject}
                  disabled={loading}
                  className="text-sm bg-red-100 hover:bg-red-200 text-red-800 px-3 py-1 rounded flex items-center"
                >
                  Reject
                </button>
              </>
            )}

            {video.status === 'in-progress' && (
              <button 
                onClick={() => setShowUploadModal(true)}
                disabled={loading}
                className="text-sm bg-blue-100 hover:bg-blue-200 text-blue-800 px-3 py-1 rounded flex items-center"
              >
                <FiUpload className="mr-1" /> Upload Edits
              </button>
            )}

            {video.status === 'needs-review' && (
              <button 
                onClick={handleMarkComplete}
                disabled={loading}
                className="text-sm bg-green-100 hover:bg-green-200 text-green-800 px-3 py-1 rounded flex items-center"
              >
                {loading ? 'Completing...' : (
                  <>
                    <FiCheck className="mr-1" /> Mark Complete
                  </>
                )}
              </button>
            )}

            {/* Always show comments button */}
            <button 
              onClick={handleAddComments}
              disabled={loading}
              className="text-sm bg-gray-100 hover:bg-gray-200 px-3 py-1 rounded flex items-center"
            >
              <FiEdit className="mr-1" /> Add Notes
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default EditorVideoCard;